//! 🛬️ An original intrinsic Pack and typed receiver settle before their unique completed value crosses a caller boundary.
use semio_framework_os_kernel as store;
use semio_framework_job::{OriginalCallerSourceLoan,OriginalConstructionDemand,OriginalSourceBinding,OriginalTurnFailure,StepContext,admit_original_construction,close_original_retained_step};
use semio_framework_value::{DslValue,RetirementDemand,RetainedCloneProgress,RetainedCloneStep,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneSource,RetainedCloneClose}};
use semio_framework_value_native_owned::{NativeReceive,owned::NativeReceivingOriginal};
use store::os_pack::intrinsic::{RetainedIntrinsicBody,RetainedIntrinsicInput};
use super::original_pack_failure::OriginalCommandPackFailure;
use std::mem::{ManuallyDrop,size_of};
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original Pack receiving requires its retained source and caller")}
fn fixed<T>()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<T>(),depth:1,..Default::default()}}
fn construction(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
fn receipt(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
/// 🧷️ Every parser, original tree, typed child and caller loan stays in its defining owner until paid closure.
pub struct OriginalPackReceiving<T:NativeReceive<DslValue>+Sync>{
 binding:OriginalSourceBinding,decoder:(u64,u64),body:usize,loan:ManuallyDrop<Option<OriginalCallerSourceLoan>>,returning:bool,
 parser:ManuallyDrop<Option<RetainedIntrinsicBody<'static>>>,failure:ManuallyDrop<Option<OriginalCommandPackFailure>>,parsed:ManuallyDrop<Option<DslValue>>,source:ManuallyDrop<Option<RetainedCloneSource<DslValue>>>,receiver:ManuallyDrop<Option<NativeReceivingOriginal<DslValue,T>>>,output:ManuallyDrop<Option<T>>,retirement:RetainedCloneClose,phase:u8,closing:bool,
}
impl<T:NativeReceive<DslValue>+Sync> OriginalPackReceiving<T>{
 /// 🎟️ The original byte allocation transfers only after the actual boxed receiving frame is funded.
 pub fn admit(bytes:&mut Vec<u8>,limits:store::os_pack::PackLimits,cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{
  let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;let maximum=usize::try_from(limits.max_total_alloc).map_err(|_|invalid())?;let d=RetirementDemand{capacity_bytes:size_of::<Self>(),..fixed::<Self>()};
  admit_original_construction(cx,output,construction(d),|control|{let(parser,failure)=match RetainedIntrinsicBody::new(RetainedIntrinsicInput::OwnedBytes(std::mem::take(bytes)),limits,maximum){Ok(parser)=>(Some(parser),None),Err((original,RetainedIntrinsicInput::OwnedBytes(original_bytes)))=>{*bytes=original_bytes;(None,Some(OriginalCommandPackFailure{original}))},Err(_)=>unreachable!()};Ok((Box::new(Self{binding,decoder:(control.ledger_identity(),control.retirement_recipient_identity().ok_or_else(invalid)?),body,loan:ManuallyDrop::new(None),returning:false,parser:ManuallyDrop::new(parser),failure:ManuallyDrop::new(failure),parsed:ManuallyDrop::new(None),source:ManuallyDrop::new(None),receiver:ManuallyDrop::new(None),output:ManuallyDrop::new(None),retirement:Default::default(),phase:0,closing:false}),receipt(d)))})
 }
 /// 🌳️ A genuine already-owned intrinsic value enters the same typed receiving continuation without encoding or reparsing it.
 pub fn admit_value(value:&mut Option<DslValue>,cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{if value.is_none(){return Err(invalid().into())}let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;let d=RetirementDemand{capacity_bytes:size_of::<Self>(),..fixed::<Self>()};admit_original_construction(cx,output,construction(d),|control|Ok((Box::new(Self{binding,decoder:(control.ledger_identity(),control.retirement_recipient_identity().ok_or_else(invalid)?),body,loan:ManuallyDrop::new(None),returning:false,parser:ManuallyDrop::new(None),failure:ManuallyDrop::new(None),parsed:ManuallyDrop::new(value.take()),source:ManuallyDrop::new(None),receiver:ManuallyDrop::new(None),output:ManuallyDrop::new(None),retirement:Default::default(),phase:2,closing:false}),receipt(d))))}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid().into())}if !self.returning{if let Some(loan)=self.loan.as_ref(){loan.validate_context(cx)?}}Ok(())}
 /// 🪜️ The original typed value becomes ready only after its input, receiver and source loan physically close.
 pub fn advance(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  self.validate(cx)?;if self.closing{return Err(invalid().into())}if cx.is_cancelled(){return Err(ValueError::literal(ValueRefusalKind::Canceled,"original Pack receiving was cancelled").into())}if self.failure.is_some(){if let Some(failure)=semio_framework_job::admit_original_domain_failure(&mut self.failure,cx)?{return Err(failure)}return Ok(false)}if self.phase==10{return Ok(true)}if cx.should_yield(){return Ok(false)}if self.loan.is_none()&&self.phase<9{*self.loan=cx.original_source_parent()?.admit_loan(cx)?;return Ok(false)}
  match self.phase{
   0=>{let parser=self.parser.as_mut().unwrap();let call=parser.advance_original_step(cx.retained_grant(),false);cx.consume_retained(call.progress)?;cx.consume_fuel(call.progress.copied_items as u64);match call.result{Err(original)=>*self.failure=Some(OriginalCommandPackFailure{original}),Ok(step)if step.complete=>self.phase=1,_=>{}}},
   1=>{let d=fixed::<DslValue>();let mut moved=None;admit_original_construction(cx,&mut moved,construction(d),|_|{*self.parsed=self.parser.as_mut().unwrap().take_output();self.phase=2;Ok(((),receipt(d)))})?;},
   2=>{let birth=RetainedCloneSource::<DslValue>::owned_constructor_demand::<()>();let d=RetirementDemand{copy_bytes:RetainedCloneSource::<DslValue>::constructor_copy_bytes(),capacity_bytes:birth.capacity_bytes,depth:birth.depth,..Default::default()};admit_original_construction(cx,&mut self.source,construction(d),|_|RetainedCloneSource::admit_owned(self.parsed.take().unwrap(),(),semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:0,maximum_depth:d.depth}).map_err(|(error,original,())|{*self.parsed=Some(original);error}))?;if self.source.is_some(){self.phase=3}},
   3=>{let d=NativeReceivingOriginal::<DslValue,T>::shell_demand();let grant=cx.retained_grant();admit_original_construction(cx,&mut self.receiver,construction(d),|_|NativeReceivingOriginal::begin_shell(grant))?;if self.receiver.is_some(){self.phase=4}},
   4=>{let receiver=self.receiver.as_mut().unwrap();let d=receiver.original_capture_demand()?;let grant=cx.retained_grant();let mut moved=None;admit_original_construction(cx,&mut moved,construction(d),|_|{let p=receiver.admit_original(&mut self.source,grant)?;self.phase=5;Ok(((),p))})?;},
   5=>{let receiver=self.receiver.as_mut().unwrap();let d=receiver.receiver_birth_demand()?;let grant=cx.retained_grant();let mut born=None;admit_original_construction(cx,&mut born,construction(d),|_|{let p=receiver.begin_receiver(grant)?;self.phase=6;Ok(((),p))})?;},
   6=>{let receiver=self.receiver.as_mut().unwrap();let grant=cx.retained_grant();let result=cx.with_native_receiving(|control|receiver.advance(control,self.body,grant));let p=match &result{Ok(step)=>step.progress(),Err(error)=>error.retained_progress()};if let Some(issued)=cx.receiving_issued_grant(){cx.consume_receiving_retained(issued,p)?}else{cx.consume_retained(p)?}cx.consume_fuel(p.copied_items as u64);result?;if receiver.output_ready(){self.phase=7}},
   7=>{let receiver=self.receiver.as_mut().unwrap();let d=receiver.take_demand()?;let grant=cx.retained_grant();admit_original_construction(cx,&mut self.output,construction(d),|_|receiver.take(grant)?.ok_or_else(invalid))?;if self.output.is_some(){receiver.begin_close();self.phase=8}},
   8=>{if self.close_sources(cx)?{let d=fixed::<u8>();let mut done=None;admit_original_construction(cx,&mut done,construction(d),|_|{self.phase=9;Ok(((),receipt(d)))})?;}},
   9=>{if let Some(loan)=self.loan.as_mut(){self.returning=true;loan.close_step(cx.original_source_parent()?,cx)?;if loan.terminal_is_empty(){self.loan.take();}}else{let d=fixed::<u8>();let mut done=None;admit_original_construction(cx,&mut done,construction(d),|_|{self.phase=10;Ok(((),receipt(d)))})?;}},
   _=>unreachable!(),
  }Ok(self.phase==10)
 }
 fn close_sources(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  if let Some(receiver)=self.receiver.as_mut(){receiver.begin_close();if !receiver.terminal_is_empty(){let d=receiver.close_demands(self.body)?;close_original_retained_step(cx,d,|grant|receiver.close_step(grant))?;return Ok(false)}let d=fixed::<Option<NativeReceivingOriginal<DslValue,T>>>();close_original_retained_step(cx,d,|_|{self.receiver.take();Ok(RetainedCloneStep::Complete(receipt(d)))})?;return Ok(false)}
  if let Some(source)=self.source.as_mut(){if !source.terminal_is_empty(){let d=source.next_close_demand(self.body)?;close_original_retained_step(cx,d,|grant|source.close_step(grant))?;return Ok(false)}let d=fixed::<Option<RetainedCloneSource<DslValue>>>();close_original_retained_step(cx,d,|_|{self.source.take();Ok(RetainedCloneStep::Complete(receipt(d)))})?;return Ok(false)}
  if self.parsed.is_some()||!self.retirement.is_empty(){let d=self.retirement.next_owner_demands::<DslValue>(self.parsed.is_some(),&None,self.body)?;close_original_retained_step(cx,d,|grant|if !self.retirement.is_empty(){self.retirement.select(self.body)?.step(grant)}else{Ok(self.retirement.begin_granted(&mut self.parsed,grant)?.unwrap_or(RetainedCloneStep::Complete(Default::default())))})?;return Ok(false)}
  if let Some(parser)=self.parser.as_mut(){if !parser.terminal_is_empty(){let call=parser.close_original_step(cx.retained_grant());cx.consume_retained(call.progress)?;cx.consume_fuel(call.progress.copied_items as u64);if let Err(original)=call.result{*self.failure=Some(OriginalCommandPackFailure{original})}return Ok(false)}let d=fixed::<Option<RetainedIntrinsicBody<'static>>>();close_original_retained_step(cx,d,|_|{self.parser.take();Ok(RetainedCloneStep::Complete(receipt(d)))})?;return Ok(false)}Ok(true)
 }
 /// 📤️ A completed value moves once; every original parsing obligation is already terminal.
 pub fn take(&mut self,cx:&mut StepContext<'_>,output:&mut Option<T>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.phase!=10||self.closing||self.output.is_none(){return Err(invalid().into())}let d=fixed::<(Option<T>,Option<T>)>();admit_original_construction(cx,output,construction(d),|_|Ok((self.output.take().unwrap(),receipt(d))))}
 /// 📐️ The mounted owner can select the actual next original child or source-return event before spending its turn.
 pub fn close_demands(&self)->Result<RetirementDemand,ValueError>{if self.failure.is_some(){return Ok(semio_framework_job::original_domain_failure_demand::<OriginalCommandPackFailure>())}if let Some(receiver)=self.receiver.as_ref(){return if receiver.terminal_is_empty(){Ok(fixed::<Option<NativeReceivingOriginal<DslValue,T>>>())}else{receiver.close_demands(self.body)}}if let Some(source)=self.source.as_ref(){return if source.terminal_is_empty(){Ok(fixed::<Option<RetainedCloneSource<DslValue>>>())}else{source.next_close_demand(self.body)}}if self.parsed.is_some()||!self.retirement.is_empty(){return self.retirement.next_owner_demands::<DslValue>(self.parsed.is_some(),&None,self.body)}if let Some(parser)=self.parser.as_ref(){return if parser.terminal_is_empty(){Ok(fixed::<Option<RetainedIntrinsicBody<'static>>>())}else{parser.original_close_demands(self.body).map_err(|_|invalid())}}if self.output.is_some(){return self.retirement.next_owner_demands::<T>(true,&None,self.body)}Ok(self.loan.as_ref().map_or(Default::default(),|loan|loan.retirement_demands()))}
 /// 🛑️ Cancellation retains each original field until its funded close finishes.
 pub fn begin_close(&mut self){self.closing=true;if let Some(receiver)=self.receiver.as_mut(){receiver.begin_close()}}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;self.begin_close();if self.failure.is_some(){if let Some(failure)=semio_framework_job::admit_original_domain_failure(&mut self.failure,cx)?{return Err(failure)}return Ok(false)}if !self.close_sources(cx)?{return Ok(false)}if self.output.is_some()||!self.retirement.is_empty(){let d=self.retirement.next_owner_demands::<T>(self.output.is_some(),&None,self.body)?;close_original_retained_step(cx,d,|grant|if !self.retirement.is_empty(){self.retirement.select(self.body)?.step(grant)}else{Ok(self.retirement.begin_granted(&mut self.output,grant)?.unwrap_or(RetainedCloneStep::Complete(Default::default())))})?;return Ok(false)}if let Some(loan)=self.loan.as_mut(){self.returning=true;loan.close_step(cx.original_source_parent()?,cx)?;if loan.terminal_is_empty(){self.loan.take();}return Ok(false)}Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{self.loan.is_none()&&self.parser.is_none()&&self.failure.is_none()&&self.parsed.is_none()&&self.source.is_none()&&self.receiver.is_none()&&self.output.is_none()&&self.retirement.is_empty()}
 pub fn release_demands()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl<T:NativeReceive<DslValue>+Sync> Drop for OriginalPackReceiving<T>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original Pack receiving requires complete funded closure")}}

